#!/usr/bin/env bash
# ISOLATED VERIFICATION ONLY. Builds a local Postgres DB in the state "Production + 115000 + move-card candidate V5".
# Never point PGHOST/PGPORT at a shared (Dev/Prod) database: the script creates roles and drops/creates $DB.
# Usage: PGHOST=/path/to/socket PGPORT=55432 PGUSER=postgres DB=sf6_release_check OUT=/path/to/generated \
#        scripts/moves/release-check/setup_isolated_db.sh [--frame-history-option]
# OUT must hold base.sql and candidate.sql generated by scripts/moves/build_all32_public_candidate_sql.py (see README).
set -euo pipefail
here="$(cd "$(dirname "$0")" && pwd)"; repo="$(cd "$here/../../.." && pwd)"
: "${DB:?}"; : "${OUT:?}"
case "${PGHOST:-}" in *supabase.co*|*supabase.com*) echo "refusing a Supabase host" >&2; exit 1;; esac
psql_() { psql -v ON_ERROR_STOP=1 -q "$@"; }
psql_ -d postgres <<'SQL'
do $r$ begin
  if not exists (select 1 from pg_roles where rolname='anon') then create role anon nologin; end if;
  if not exists (select 1 from pg_roles where rolname='authenticated') then create role authenticated nologin; end if;
  if not exists (select 1 from pg_roles where rolname='service_role') then create role service_role nologin bypassrls; end if;
  if not exists (select 1 from pg_roles where rolname='authenticator') then create role authenticator login password 'localonly' noinherit; end if;
end $r$;
SQL
psql_ -d postgres -c "drop database if exists $DB" -c "create database $DB" \
  -c "alter database $DB set search_path to \"\$user\", public, extensions"  # Supabase default: extensions schema on the path
# Schema only (no data): local stubs of the Supabase auth/storage/cron objects + repo migrations up to 20260922
# (identical to the 196 migrations Production lists). Data migrations need Production rows, so the chain is
# shipped as this schema snapshot instead of being replayed. Then 115000 (required for the move cards).
psql_ -d "$DB" -f "$here/schema_prod_chain_20260922.sql"
psql_ -d "$DB" -f "$repo/supabase/migrations/20261120115000_move_commands_policy_definer_source_check.sql"
psql_ -d "$DB" -f "$OUT/base.sql"
psql_ -d "$DB" -f "$OUT/candidate.sql"
if [ "${1:-}" = "--frame-history-option" ]; then psql_ -d "$DB" -f "$here/frame_history_rls_option.sql"; fi
psql -At -d "$DB" -c "select 'published moves', count(*) from moves where status='published'" -c "select 'current patch', version_label from patches where is_current"
